namespace notesos {
// Diagnostics are a separate bounded ring, never the completion/event authority.
class Diagnostics {
 struct Record{uint64_t at=0;uint32_t seq=0,owner=0;uint8_t severity=0;char layer[12]{},source[48]{},code[48]{},message[128]{};};
 Core&core_;Record*records_=nullptr;size_t capacity_=0,retained_=0;uint32_t sequence_=0,overwritten_=0,suppressed_=0;bool enabled_=true;unsigned level_=2,rate_=20,count_=0;uint64_t window_=0;mutable std::mutex mutex_;
 uint64_t calls_=0,aiCalls_=0,errors_=0,inputs_=0,activeMs_=0,lastInput_=0,lastPoll_=0;
 template<size_t N>static void text(char(&out)[N],const char*value){size_t used=0;auto p=(const unsigned char*)value;while(*p&&used<N-1){unsigned n=*p<0x80?1:*p>=0xc2&&*p<=0xdf?2:*p>=0xe0&&*p<=0xef?3:*p>=0xf0&&*p<=0xf4?4:0;bool valid=n;for(unsigned i=1;i<n;++i)if(!p[i]||(p[i]&0xc0)!=0x80){valid=false;break;}if(valid&&n==3&&((*p==0xe0&&p[1]<0xa0)||(*p==0xed&&p[1]>=0xa0)))valid=false;if(valid&&n==4&&((*p==0xf0&&p[1]<0x90)||(*p==0xf4&&p[1]>=0x90)))valid=false;if(!valid){out[used++]='?';++p;continue;}if(used+n>=N)break;memcpy(out+used,p,n);used+=n;p+=n;}out[used]=0;}

 static bool backpressure(const char*e){return e&&Core::containsMethod("resource_busy,spi_busy,operation_active",e);}
 static unsigned level(const char*s){const char*names[]={"trace","debug","info","warn","error","fatal"};for(unsigned i=0;i<6;++i)if(!strcmp(names[i],s))return i;return 6;}
 static const char*name(unsigned i){const char*names[]={"trace","debug","info","warn","error","fatal"};return i<6?names[i]:"error";}
public:
 using Save=bool(*)(const char*,size_t);
 explicit Diagnostics(Core&c):core_(c){}~Diagnostics(){core_.resources().freeAllocation(records_);}
 void append(unsigned severity,const char*layer,const char*source,const char*code,const char*message="",uint32_t owner=0){std::lock_guard<std::mutex>lock(mutex_);if(!enabled_||severity<level_||!capacity_)return;uint64_t now=core_.now();if(now-window_>=1000){window_=now;count_=0;}if(count_++>=rate_){++suppressed_;return;}auto&r=records_[sequence_%capacity_];if(retained_==capacity_)++overwritten_;else ++retained_;r={};r.seq=++sequence_;r.at=now;r.owner=owner;r.severity=severity;text(r.layer,layer);text(r.source,source);text(r.code,code);text(r.message,message);}
 void event(const char*source,const char*event,JsonObjectConst data,uint32_t owner){if(!strcmp(source,"/dev/buttons")&&!strcmp(event,"press")){std::lock_guard<std::mutex>lock(mutex_);++inputs_;lastInput_=core_.now();}if(!strcmp(event,"log")){append(2,"application",source,"print",data["message"]|"",owner);return;}if(strstr(event,"failed")||!strcmp(event,"fault")||!strcmp(event,"delivery_error")){{std::lock_guard<std::mutex>lock(mutex_);++errors_;}append(4,!strncmp(source,"/dev/",5)||!strncmp(source,"/net/",5)?"driver":"system",source,data["error"]|event,"",owner);}else if(Core::containsMethod("connected,disconnected,started,stopped,launched,configuration_applied",event))append(2,!strncmp(source,"/dev/",5)||!strncmp(source,"/net/",5)?"driver":"system",source,event,"",owner);}
 void call(const char*path,const char*method,const char*error,uint32_t owner){if(!strcmp(path,"/sys/logs")||!strcmp(path,"/sys/telemetry"))return;{std::lock_guard<std::mutex>lock(mutex_);if(owner)++calls_;if(!error&&!strcmp(path,"/services/ai")&&!strcmp(method,"submit"))++aiCalls_;if(error&&!backpressure(error))++errors_;}if(error)append(backpressure(error)?1:4,owner?"application":"system",path,error,"",owner);else append(0,owner?"application":"system",path,method,"",owner);}
 void poll(uint64_t now){std::lock_guard<std::mutex>lock(mutex_);if(lastPoll_&&lastInput_&&now-lastInput_<60000)activeMs_+=now-lastPoll_;lastPoll_=now;}
 void counters(JsonObject o)const{std::lock_guard<std::mutex>lock(mutex_);sizeText(o,"application_calls",calls_);sizeText(o,"ai_requests",aiCalls_);sizeText(o,"uptime_ms",core_.now());sizeText(o,"errors",errors_);sizeText(o,"input_actions",inputs_);sizeText(o,"active_ms",activeMs_);}
 const char*configure(JsonObjectConst a,Save save=nullptr,bool persist=false){for(auto f:a)if(!Core::containsMethod("enabled,level,capacity,rate_per_second",f.key().c_str()))return "unknown_log_setting";bool enabled=a["enabled"]|enabled_;unsigned severity=a.containsKey("level")?level(a["level"]|""):level_;unsigned capacity=a["capacity"]|unsigned(capacity_?capacity_:16),rate=a["rate_per_second"]|rate_;
 if(a.containsKey("enabled")&&!a["enabled"].is<bool>()||severity>5||!capacity||capacity>1024||!rate||rate>1000)return "log_configuration";for(auto key:{"capacity","rate_per_second"})if(a.containsKey(key)&&!a[key].is<unsigned>())return "log_configuration";
 Record*next=records_;if(capacity!=capacity_){next=(Record*)core_.resources().allocate(capacity*sizeof(Record));if(!next)return "log_memory_budget";memset(next,0,capacity*sizeof(Record));}
 JsonDocument d;d["enabled"]=enabled;d["level"]=name(severity);d["capacity"]=capacity;d["rate_per_second"]=rate;char text[192];size_t n=serializeJson(d,text,sizeof text);if(persist&&(!save||!save(text,n))){if(next!=records_)core_.resources().freeAllocation(next);return "persistence_failed";}
 std::lock_guard<std::mutex>lock(mutex_);if(next!=records_){size_t kept=std::min(retained_,size_t(capacity));for(size_t i=0;i<kept;++i){uint32_t seq=sequence_-kept+i+1;next[(seq-1)%capacity]=records_[(seq-1)%capacity_];}overwritten_+=retained_-kept;retained_=kept;core_.resources().freeAllocation(records_);records_=next;capacity_=capacity;}enabled_=enabled;level_=severity;rate_=rate;return nullptr;}
 const char*invoke(const char*m,JsonObjectConst a,JsonObject o,Save save=nullptr){if(auto e=argumentFields(a,!strcmp(m,"configure")?"settings,persist":!strcmp(m,"write")?"level,code,message":"after,limit,layer,owner"))return e;if(!strcmp(m,"configure")){if(!a["settings"].is<JsonObjectConst>())return "log_configuration";if(auto e=configure(a["settings"],save,a["persist"]|false))return e;}
 else if(!strcmp(m,"write")){auto severity=level(a["level"]|"info");if(severity>5||!a["message"].is<const char*>()||strlen(a["message"])>127)return "log_entry";append(severity,"application","/sys/logs",a["code"]|"application",a["message"],core_.callerOwner());return nullptr;}
 else if(strcmp(m,"read"))return "unsupported_method";
 std::lock_guard<std::mutex>lock(mutex_);o["enabled"]=enabled_;o["level"]=name(level_);o["capacity"]=capacity_;o["rate_per_second"]=rate_;o["overwritten"]=overwritten_;o["suppressed"]=suppressed_;o["latest"]=sequence_;o["persistent"]=false;uint32_t after=a["after"]|0u,oldest=sequence_-retained_+1;o["gap"]=after<oldest-1;auto list=o["records"].to<JsonArray>();unsigned limit=a["limit"]|4u;if(limit>8||!limit)return "log_page_limit";uint32_t cursor=after;for(uint32_t i=std::max(after+1,oldest);i<=sequence_;++i){auto&r=records_[(i-1)%capacity_];cursor=i;if(a.containsKey("layer")&&strcmp(a["layer"]|"",r.layer)||a.containsKey("owner")&&a["owner"].as<uint32_t>()!=r.owner)continue;auto item=list.add<JsonObject>();item["sequence"]=r.seq;item["at_ms"]=r.at;item["level"]=name(r.severity);item["layer"]=r.layer;item["source"]=r.source;item["code"]=r.code;item["message"]=r.message;item["owner"]=r.owner;if(measureJson(o)>MAX_WIRE-256){list.remove(list.size()-1);cursor=i-1;break;}if(list.size()>=limit)break;}o["cursor"]=cursor;o["more"]=cursor<sequence_;return nullptr;}
 void describe(JsonObject o)const{o["scope"]="system";o["storage"]="bounded_ram_ring";o["levels"]="trace,debug,info,warn,error,fatal";o["layers"]="system,driver,application";o["writes_on_capture"]=0;o["overflow"]="overwrite_oldest";o["persistent_export"]="explicit_collector_via_fs_or_network";o["message_max_bytes"]=127;o["capacity_range"]="1..1024_subject_to_memory_admission";o["rate_per_second_range"]="1..1000";o["filter_fields"]="layer,owner";}
};
}
